export function normalizeClassKey(classKey: string): string {
  if (!classKey) return "1st";
  const s = String(classKey).trim().toLowerCase();
  if (s.includes("1") || s.includes("१")) return "1st";
  if (s.includes("2") || s.includes("२")) return "2nd";
  if (s.includes("3") || s.includes("३")) return "3rd";
  if (s.includes("4") || s.includes("४")) return "4th";
  if (s.includes("5") || s.includes("५")) return "5th";
  if (s.includes("6") || s.includes("६")) return "6th";
  if (s.includes("7") || s.includes("७")) return "7th";
  if (s.includes("8") || s.includes("८")) return "8th";
  if (s.includes("9") || s.includes("९")) return "9th";
  if (s.includes("10") || s.includes("१०")) return "10th";
  return s;
}

